        if line.starts_with("MemAvailable:") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let kb: u64 = parts[1].parse().ok()?;
                let gb = kb as f64 / 1024.0 / 1024.0;
                return Some(gb);
            }
        }
    }

    None
}

