    /// Executes a single inference task with semaphore control.
    async fn execute_single_inference_task(
        &self,
        model_name: String,
        prompt: String,
        request_config: ChatCompletionRequest,
    ) -> Result<InferenceResult> {
        let client = LlamaHttpClient::new(&self.config.server_url)?;

        // Acquire semaphore permit for concurrency control
        let _permit = self.inference_semaphore.clone().acquire_owned().await?;

        info!(
            "[benchmark] [{}] Starting inference for model '{}' with prompt length: {} tokens",
            model_name, request_config.model_id, prompt.len() / 4 // rough token estimate
        );

        let start_time = Instant::now();

        match client.chat_completion(request_config).await {
            Ok(response) => {
                info!(
                    "[benchmark] [{}] Inference completed in {:.2}s", 
                    model_name, start_time.elapsed().as_secs_f64()
                );

                let result = InferenceResult::new(
                    &model_name,
                    prompt.clone(),
                    response.choices[0].message.content.clone(),
                    Some(start_time.elapsed()),
                );
                Ok(result)
            }
            Err(e) => {
                error!(
                    "[benchmark] [{}] Inference failed for model '{}': {}", 
                    model_name, request_config.model_id, e
                );

                // Create a failure result to maintain parallel structure integrity
                let result = InferenceResult::new(
                    &model_name,
                    prompt.clone(),
                    String::from("Error: Failed to complete inference"),
                    Some(start_time.elapsed()),
                );
                Ok(result)
            }
        }
    }

    /// Executes parallel inference for the same model across multiple targets (prompts).
    /// This function replaces sequential execution with a fully parallelized JoinSet approach.
    pub async fn execute_parallel_inference_route(
        &self,
        model_name: String,
        prompts: Vec<String>,
        request_config: ChatCompletionRequest,
    ) -> Result<Vec<InferenceResult>> {
        let mut join_set = JoinSet::new();

        info!(
            "[benchmark] [{}] Starting parallel inference route for {} targets", 
            model_name, prompts.len()
        );

        // Spawn tasks for all prompts in the same model batch
        for (index, prompt) in prompts.iter().enumerate() {
            let config = request_config.clone();

            join_set.spawn(async move {
                self.execute_single_inference_task(model_name.clone(), prompt.clone(), config).await
            });
        }

        // Drain and collect results from JoinSet
        let mut results: Vec<InferenceResult> = Vec::new();

        while let Some(result) = join_set.join_next().await {
            match result {
                Ok(Ok(inference_result)) => {
                    info!("[benchmark] [{}] Successfully processed target", model_name);
                    results.push(inference_result);
                }
                Ok(Err(e)) => {
                    error!("[benchmark] [{}] Task failed: {}", model_name, e);
                    // Add a failure placeholder to maintain vector integrity if needed, 
                    // or handle strictly based on application logic. Here we push an error result.
                    results.push(InferenceResult::new(
                        &model_name,
                        String::from("Error"),
                        format!("Task failed: {}", e),
                        None,
                    ));
                }
                Err(e) => {
                    error!("[benchmark] [{}] JoinSet drain error: {}", model_name, e);
                    results.push(InferenceResult::new(
                        &model_name,
                        String::from("Error"),
                        format!("JoinSet drain failed: {}", e),
                        None,
                    ));
                }
            }
        }

        info!(
            "[benchmark] [{}] Parallel inference route completed. Total results: {}", 
            model_name, results.len()
        );

        // Verify result mapping accuracy (ensure count matches input)
        if results.len() != prompts.len() {
            warn!(
                "[benchmark] Result count mismatch for model '{}'. Expected {}, got {}",
                model_name, prompts.len(), results.len()
            );
        }

        Ok(results)
    }

