            "[benchmark] [{}] Parallel inference route completed. Total results: {}", 
            model_name, results.len()
        );

        // Verify result mapping accuracy (ensure count matches input)
        if results.len() != prompts.len() {
            warn!(
                "[benchmark] Result count mismatch for model '{}'. Expected {}, got {}",
                model_name, prompts.len(), results.len()
            );
        }

        Ok(results)
    }
