            .and_then(|v| v.as_f64())
            .or_else(|| self.config.top_p)
            .unwrap_or(1.0); // Default if not specified anywhere

        // Build ChatCompletionRequest struct
        let mut messages: Vec<ChatMessage> = vec![];

        // Assuming single prompt for now, can be expanded to handle multi-turn if needed
        if !prompt.is_empty() {
            messages.push(ChatMessage::User(prompt.to_string()));
        }

