fn detect_vram_gb() -> Option<f64> {
    if let Some(vram_kb) = read_sysfs_vram_amd() {
        let vram_gb = vram_kb as f64 / 1024.0 / 1024.0;
        return Some(vram_gb);
    }

    if let Some(vram_mb) = read_proc_vram_nvidia() {
        let vram_gb = vram_mb as f64 / 1024.0;
        return Some(vram_gb);
    }

